// spec: specs/orders.md §23 · кейс .qa/tests/orders/ord-38-edit-items-layout-widths.md
// seed: tests/seed.admin.spec.ts
// #cb3f40 (עבר QA 26.10, rej_c92f2546 закрыт) + #c6b040 (עבר QA 26.10): «עריכת הזמנה», карточка «פריטי ההזמנה».
//   Раскладка — по ширине карточки (container query 600px): уже 600 — ряды (имя + удаление; кол-во · цена; «סה"כ» отдельным
//   рядом), шире — таблица. Проверяется результат: нет горизонтальной прокрутки страницы и карточки; «הסרת <שם>» в карточке и
//   elementFromPoint по центру попадает в неё; суммы строки ₪1,000.00 / ₪10,000.00 / ₪100,000.00 целиком и не пересекают поле
//   цены; фокус на цене не сдвигает имя; сообщения под строкой — внутри карточки. Длинное имя — nowrap + ellipsis в карточке (норма,
//   как #e1e502). Ширина поля цены (≥160px, 50000 / 500000.50 целиком) — отдельный тест order-edit-price-field-width.spec.ts (#af3ea6).
// Правка 26.10 (#af3ea6): раскладка определяется шириной блока container query, а не окна. На 715 блок 609px ≥ 600 → ТАБЛИЦА
//   (раньше в плане/названии было «641–715 — ряды»); 641/700 — ряды. Ожидаемая раскладка каждой ширины задана явно (LAYOUT).
// Цены и кол-во вводятся БЕЗ сохранения — в конце «ביטול», заказ прежний.
// Данные: товар QA-AUTO-cb3f-<ts> <длинное имя> (₪1, остаток 3 «ללא מקום») + заказ клиента test ×1; afterAll — отклонить, удалить.
import { test, expect, Page } from '@playwright/test';
import { auth, createStockedProduct, buyerPlaceOrder, openOrder, cleanup } from './_qa-order';

test.use({ storageState: auth('admin') });
test.describe.configure({ mode: 'serial' });

const ts = `${String(Date.now()).slice(-7)}${Math.floor(Math.random() * 10)}`;
const P = `QA-AUTO-cb3f-${ts} שם מוצר ארוך מאוד לבדיקת תצוגה בעריכת הזמנה בטלפון`;
let orderNo: string | undefined;
let productCreated = false;

const qty = (page: Page) => page.getByRole('textbox', { name: `כמות — ${P}`, exact: true });
const price = (page: Page) => page.getByRole('spinbutton', { name: `מחיר יחידה — ${P}`, exact: true });
const cardRow = (page: Page) => page.getByText(P, { exact: true }).first().locator('..');

type Box = { l: number; t: number; r: number; b: number };
type M = {
  vw: number; docSW: number; cardSW: number; cardCW: number; scrollers: string[]; card: Box; hdrVisible: boolean;
  name: Box | null; nameWS: string; nameTO: string; price: Box; tot: string | null; totBox: Box | null; totClip: boolean;
  del: Box; delHit: string | null | undefined; containerW: number; msgs: { t: string; box: Box; clip: boolean }[]; scrollX: number;
};

/** Замер карточки «פריטי ההזמנה» и строки товара (только чтение DOM). */
const measure = (page: Page): Promise<M> => page.evaluate((n) => {
  const box = (e: Element | null | undefined) => { if (!e) return null; const b = e.getBoundingClientRect(); return { l: b.left, t: b.top, r: b.right, b: b.bottom }; };
  const h = [...document.querySelectorAll('h1,h2,h3,h4')].find((e) => e.textContent!.trim() === 'פריטי ההזמנה')!;
  const card = h.parentElement!;
  const vis = (e: Element) => e.getClientRects().length > 0 && getComputedStyle(e).visibility !== 'hidden';
  const scrollers = [card, ...card.querySelectorAll('*')].filter((e) => vis(e) && e.scrollWidth > e.clientWidth + 1 && ['auto', 'scroll'].includes(getComputedStyle(e).overflowX))
    .map((e) => `${e.tagName} sw${e.scrollWidth}/cw${e.clientWidth}`);
  const hdr = [...card.querySelectorAll('*')].find((e) => e.children.length === 0 && e.textContent!.trim() === 'שם מוצר');
  const pi = document.querySelector(`input[aria-label="מחיר יחידה — ${n}"]`)!;
  const del = document.querySelector(`button[aria-label="הסרת ${n}"]`)!;
  let row: Element | null = pi; while (row && !row.contains(del)) row = row.parentElement;
  const leaves = [...row!.querySelectorAll('*')].filter((e) => e.children.length === 0 && vis(e));
  const nameEl = leaves.find((e) => e.textContent!.trim() === n) as HTMLElement | undefined;
  const totEl = leaves.filter((e) => /^₪[\d,]+\.\d\d$/.test(e.textContent!.trim())).pop() as HTMLElement | undefined;
  del.scrollIntoView({ block: 'center' });
  const db = del.getBoundingClientRect();
  const hit = document.elementFromPoint(db.left + db.width / 2, db.top + db.height / 2)?.closest('button')?.getAttribute('aria-label');
  const msgs = [...card.querySelectorAll('*')]
    .filter((e) => e.children.length <= 1 && vis(e) && /בלבד|מספר שלם|מחיר במחירון|המחיר שונה/.test(e.textContent!) && !/המחירים מחושבים/.test(e.textContent!))
    .filter((e, _i, a) => !a.some((o) => o !== e && e.contains(o)))
    .map((e) => ({ t: e.textContent!.trim().slice(0, 80), box: box(e)!, clip: e.scrollWidth > e.clientWidth + 1 }));
  const cs = nameEl ? getComputedStyle(nameEl) : null;
  return {
    vw: innerWidth, docSW: document.documentElement.scrollWidth, cardSW: card.scrollWidth, cardCW: card.clientWidth, scrollers,
    card: box(card)!, hdrVisible: !!hdr && vis(hdr), name: box(nameEl), nameWS: cs?.whiteSpace ?? '', nameTO: cs?.textOverflow ?? '',
    price: box(pi)!, tot: totEl ? totEl.textContent!.trim() : null, totBox: box(totEl), totClip: totEl ? totEl.scrollWidth > totEl.clientWidth + 1 : true,
    del: box(del)!, delHit: hit, msgs, scrollX,
    containerW: (pi.closest('[class*="@container"]') ?? card).getBoundingClientRect().width,
  };
}, P);

const inside = (a: Box, c: Box) => a.l >= c.l - 0.5 && a.r <= c.r + 0.5;
const overlap = (a: Box, b: Box) => Math.max(0, Math.min(a.r, b.r) - Math.max(a.l, b.l)) * Math.max(0, Math.min(a.b, b.b) - Math.max(a.t, b.t));
const fmt = (n: number) => '₪' + n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

/** Ожидаемая раскладка по ширине окна (правило: блок container query < 600px — ряды, иначе таблица; 1024/1280 — с открытым меню). */
const LAYOUT: Record<number, 'rows' | 'table'> = {
  320: 'rows', 360: 'rows', 390: 'rows', 414: 'rows', 667: 'rows',
  641: 'rows', 700: 'rows', 715: 'table', 1024: 'rows', 1280: 'rows', 1440: 'table',
};

/** Все проверки на одной ширине; контейнер уже 600 — ожидаются ряды, иначе таблица. */
async function checkWidth(page: Page, W: number, H: number) {
  await page.setViewportSize({ width: W, height: H });
  await expect.poll(() => page.evaluate(() => innerWidth)).toBe(W);
  await qty(page).fill('2');
  await qty(page).press('Tab');

  // базовый замер + фокус на цене не сдвигает имя
  const before = await measure(page);
  const narrow = before.containerW < 600; // ширина контейнера container query (600px)
  expect(narrow ? 'rows' : 'table', `${W}: блок ${Math.round(before.containerW)}px → ожидается ${LAYOUT[W]}`).toBe(LAYOUT[W]);
  await price(page).focus();
  const focused = await measure(page);
  expect(focused.name, `${W}: имя видно`).not.toBeNull();
  expect(Math.abs(focused.name!.l - before.name!.l), `${W}: фокус на цене не сдвигает имя (лево)`).toBeLessThanOrEqual(1);
  expect(Math.abs(focused.name!.r - before.name!.r), `${W}: фокус на цене не сдвигает имя (право)`).toBeLessThanOrEqual(1);
  expect(focused.scrollX, `${W}: окно не прокручено вбок`).toBe(0);

  for (const p of [500, 5000, 50000]) {
    await price(page).fill(String(p));
    await price(page).press('Tab');
    await expect(page.getByText(fmt(p * 2), { exact: true }).first(), `${W}: сумма строки ${fmt(p * 2)}`).toBeVisible();
    const m = await measure(page);
    const tag = `${W}px, цена ${p}`;
    expect(m.docSW, `${tag}: нет горизонтальной прокрутки страницы`).toBeLessThanOrEqual(m.vw + 1);
    expect(m.cardSW, `${tag}: нет прокрутки карточки «פריטי ההזמנה»`).toBeLessThanOrEqual(m.cardCW + 1);
    expect(m.scrollers, `${tag}: внутри карточки нет прокручиваемых вбок блоков`).toEqual([]);
    expect(inside(m.del, m.card), `${tag}: «הסרת …» внутри карточки`).toBe(true);
    expect(m.delHit, `${tag}: центр «הסרת …» — сама кнопка`).toBe(`הסרת ${P}`);
    expect(m.tot, `${tag}: сумма строки`).toBe(fmt(p * 2));
    expect(m.totClip, `${tag}: сумма строки не обрезана`).toBe(false);
    expect(inside(m.totBox!, m.card), `${tag}: сумма строки внутри карточки`).toBe(true);
    expect(overlap(m.totBox!, m.price), `${tag}: сумма не заходит под поле цены`).toBe(0);
    expect(inside(m.price, m.card), `${tag}: поле цены внутри карточки`).toBe(true);
    expect(inside(m.name!, m.card), `${tag}: имя внутри карточки`).toBe(true);
    if (narrow) {
      expect(m.hdrVisible, `${tag}: карточка < 600 — заголовки таблицы скрыты (ряды)`).toBe(false);
      expect(m.totBox!.t, `${tag}: «סה"כ» строки — отдельным рядом ниже поля цены`).toBeGreaterThanOrEqual(m.price.b - 0.5);
    } else {
      expect(m.hdrVisible, `${tag}: карточка ≥ 600 — таблица с заголовками`).toBe(true);
    }
  }
  // длинное имя: одна строка с многоточием, в карточке (норма)
  expect(before.nameWS, `${W}: имя nowrap`).toBe('nowrap');
  expect(before.nameTO, `${W}: имя с многоточием`).toBe('ellipsis');

  // сообщения под строкой: «המחיר שונה…» (цена 50000), «מספר שלם בלבד» (1.5), «במלאי 3 בלבד» (4) — внутри карточки
  for (const [v, text] of [['1.5', 'כמות — מספר שלם בלבד'], ['4', 'במלאי 3 בלבד — לא ניתן להזמין יותר']] as const) {
    await qty(page).fill(v);
    await qty(page).press('Tab');
    await expect(page.getByText(text, { exact: true }), `${W}: сообщение «${text}»`).toBeVisible();
    const m = await measure(page);
    expect(m.msgs.some((x) => x.t.includes('המחיר שונה להזמנה זו בלבד')), `${W}: есть пометка изменённой цены`).toBe(true);
    expect(m.msgs.some((x) => x.t.includes(text)), `${W}: сообщение найдено в карточке`).toBe(true);
    for (const x of m.msgs) {
      expect(inside(x.box, m.card), `${W}: «${x.t}» внутри карточки`).toBe(true);
      expect(x.box.l >= -0.5 && x.box.r <= m.vw + 0.5, `${W}: «${x.t}» внутри экрана`).toBe(true);
    }
    expect(m.docSW, `${W}, сообщение ${v}: нет горизонтальной прокрутки страницы`).toBeLessThanOrEqual(m.vw + 1);
    expect(m.cardSW, `${W}, сообщение ${v}: нет прокрутки карточки`).toBeLessThanOrEqual(m.cardCW + 1);
  }
  await qty(page).fill('2');
  await qty(page).press('Tab');
}

async function openEditAndRun(page: Page, sizes: [number, number][]) {
  await page.setViewportSize({ width: 1440, height: 900 }); // список заказов — в десктопной раскладке
  await openOrder(page, orderNo!);
  await page.getByRole('button', { name: 'עריכה', exact: true }).click();
  await expect(page.getByRole('heading', { level: 1, name: `עריכת הזמנה #${orderNo}` })).toBeVisible({ timeout: 20_000 });
  await expect(qty(page)).toHaveValue('1');
  for (const [w, h] of sizes) await checkWidth(page, w, h);
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.getByRole('button', { name: 'ביטול', exact: true }).click(); // ничего не сохраняем
  await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${orderNo}` })).toBeVisible({ timeout: 20_000 });
  await expect(cardRow(page), 'заказ не изменился').toHaveText(/—\s*1\s*₪1\.00\s*₪1\.00/);
}

test.describe('orders — עריכת הזמנה: «פריטי ההזמנה» בלי גלילה לרוחב בכל רוחב (#cb3f40 #c6b040)', () => {
  test.beforeAll(async ({ browser }) => {
    test.setTimeout(240_000);
    const ctx = await browser.newContext({ storageState: auth('admin'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    let id: string;
    try {
      productCreated = true;
      id = await createStockedProduct(await ctx.newPage(), P, `QCB3F-${ts}`, 1, 3);
    } finally { await ctx.close(); }
    orderNo = await buyerPlaceOrder(browser, [{ id, name: P, qty: 1 }], `QA-AUTO-cb3f-${ts}`);
  });
  test.afterAll(async ({ browser }) => {
    test.setTimeout(180_000);
    await cleanup(browser, [orderNo], productCreated ? [P] : []);
  });

  test('טלפון 320/360/390/414 ולרוחב 667×375: שורות, «סה"כ» ₪1,000–₪100,000 במלואו, מחיקה בתוך הכרטיס, הודעות בתוך הכרטיס #cb3f40 #c6b040 @iphone @orders @data', async ({ page }) => {
    test.setTimeout(240_000);
    await openEditAndRun(page, [[320, 568], [360, 740], [390, 844], [414, 896], [667, 375]]);
  });

  test('641/700 שורות, 715 טבלה (בלוק 609px), 1024/1280 עם סרגל צד שורות, 1440 טבלה: בלי גלילה לרוחב, מחיקה בתוך הכרטיס ונלחצת, סכומים במלואם #c6b040 #cb3f40 @desktop @orders @data', async ({ page }) => {
    test.setTimeout(240_000);
    await openEditAndRun(page, [[641, 900], [700, 900], [715, 900], [1024, 768], [1280, 800], [1440, 900]]);
  });
});
